  title: 'Seventy-Nine Years of the 57th Street Art Fair',
  category: 'spotlight',
  author_name: 'Julian Vane',
  date: '2026-06-09',
  event_dates: 'June 6 – 7, 2026',
  venue: '57th Street between Kenwood and Woodlawn',
  neighborhood: 'Hyde Park',
  featured: false,
  cover_image: "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Hull_Court_Gate%2C_University_of_Chicago%2C_57th_Street%2C_Hyde_Park%2C_Chicago%2C_IL%3B_November_2023_%28_%2854516026264%29.jpg/1920px-Hull_Court_Gate%2C_University_of_Chicago%2C_57th_Street%2C_Hyde_Park%2C_Chicago%2C_IL%3B_November_2023_%28_%2854516026264%29.jpg",
  cover_credit: "Warren LeMay from Chicago, IL, United States / Wikimedia Commons (CC BY-SA 2.0)",
